const state={activeHex:'#9B435C',family:'All',search:'lipstick',selected:null,compare:[],scanStream:null,skinStream:null,skinShades:[],skinType:'Lipstick',skinAnchor:{x:.5,y:.55},skinLoop:0};
const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));
function hexToRgb(hex){const value=hex.replace('#','');return{r:parseInt(value.slice(0,2),16),g:parseInt(value.slice(2,4),16),b:parseInt(value.slice(4,6),16)}}
function rgbToHex(r,g,b){return '#'+[r,g,b].map(value=>clamp(Math.round(value),0,255).toString(16).padStart(2,'0')).join('').toUpperCase()}
function rgbToLab(r,g,b){let [R,G,B]=[r,g,b].map(v=>{v/=255;return v>.04045?((v+.055)/1.055)**2.4:v/12.92});let x=(R*.4124+G*.3576+B*.1805)/.95047,y=(R*.2126+G*.7152+B*.0722),z=(R*.0193+G*.1192+B*.9505)/1.08883;[x,y,z]=[x,y,z].map(v=>v>.008856?Math.cbrt(v):7.787*v+16/116);return{L:116*y-16,a:500*(x-y),b:200*(y-z)}}
function hexToLab(hex){const c=hexToRgb(hex);return rgbToLab(c.r,c.g,c.b)}
function distance(a,b){const p=hexToLab(a),q=hexToLab(b);return Math.hypot(p.L-q.L,p.a-q.a,p.b-q.b)}
function matchScore(hex){return Math.round(clamp(100-distance(state.activeHex,hex)*2,62,99))}
function closest(limit=products.length){return products.slice().sort((a,b)=>distance(state.activeHex,a.hex)-distance(state.activeHex,b.hex)).slice(0,limit)}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function productCard(product,compact=false){return `<article class="product-card" data-product="${product.id}"><div class="product-image" style="--pos:${product.pos}"><img src="assets/lip-products.png" alt="${product.brand} ${product.shade} lip colour"><span class="match">${matchScore(product.hex)}% shade match</span>${product.verified?'<span class="verified">✓ Reference checked</span>':''}</div><div class="product-body"><span class="product-brand">${product.brand}</span><h3>${product.name}</h3><div class="product-shade"><i style="--shade:${product.hex}"></i><span>${product.shade} · ${product.hex}</span></div><div class="product-price">₹${product.price}<del>₹${product.mrp}</del></div><div class="product-rating"><b>${product.rating} ★</b><span>${product.reviews.toLocaleString('en-IN')} Reviews</span></div>${compact?'':`<div class="card-actions"><button type="button" data-try="${product.id}">Try this shade</button><button class="compare-toggle ${state.compare.includes(product.id)?'is-active':''}" type="button" data-compare="${product.id}" aria-label="Add ${product.shade} to comparison">${state.compare.includes(product.id)?'✓':'＋'}</button></div>`}</div></article>`}
function currentFilters(){return{types:$$('input[name=type]:checked').map(x=>x.value),finishes:$$('input[name=finish]:checked').map(x=>x.value),rating:$('#ratingFour').checked,verified:$('#verifiedOnly').checked}}
function filteredProducts(){const f=currentFilters(),query=state.search.trim().toLowerCase();let list=products.filter(p=>f.types.includes(p.type)&&(!f.finishes.length||f.finishes.includes(p.finish))&&(!f.rating||p.rating>=4)&&(!f.verified||p.verified)&&(state.family==='All'||p.family===state.family)&&(!query||`${p.brand} ${p.name} ${p.shade} ${p.hex} ${p.family}`.toLowerCase().includes(query)||query==='lipstick'));const sort=$('#sortSelect').value;if(sort==='match')list.sort((a,b)=>distance(state.activeHex,a.hex)-distance(state.activeHex,b.hex));if(sort==='rating')list.sort((a,b)=>b.rating-a.rating);if(sort==='priceLow')list.sort((a,b)=>a.price-b.price);if(sort==='priceHigh')list.sort((a,b)=>b.price-a.price);return list}
function renderProducts(){const list=filteredProducts();$('#productGrid').innerHTML=list.map(product=>productCard(product)).join('');$('#resultCount').textContent=list.length;$('#emptyState').hidden=!!list.length;wireProductCards($('#productGrid'))}
function wireProductCards(root){$$('[data-product]',root).forEach(card=>card.addEventListener('click',event=>{if(event.target.closest('[data-try],[data-compare]'))return;openProduct(card.dataset.product)}));$$('[data-try]',root).forEach(button=>button.addEventListener('click',()=>openFace(products.find(p=>p.id===button.dataset.try))));$$('[data-compare]',root).forEach(button=>button.addEventListener('click',()=>toggleCompare(button.dataset.compare)))}
function toggleCompare(id){const index=state.compare.indexOf(id);if(index>=0)state.compare.splice(index,1);else if(state.compare.length<4)state.compare.push(id);else return toast('You can compare up to four shades.');renderCompare();renderProducts()}
function renderCompare(){const selected=state.compare.map(id=>products.find(p=>p.id===id)).filter(Boolean);$('#compareDock').hidden=!selected.length;$('#compareNames').textContent=selected.map(p=>p.shade).join(' · ');$('#compareChips').innerHTML=selected.map(p=>`<i style="--c:${p.hex}" title="${p.shade}"></i>`).join('')}
function setReference(hex){state.activeHex=hex.toUpperCase();$('#activeColourChip').style.background=state.activeHex;$('#activeColourText').textContent=state.activeHex;$('#bannerHex').textContent=state.activeHex;renderProducts();renderScanMatches()}
function openProduct(id){const p=products.find(item=>item.id===id);if(!p)return;state.selected=p;$('#listingView').hidden=true;$('#productView').hidden=false;$('#detailBrand').textContent=p.brand;$('#detailName').textContent=p.name;$('#detailShade').textContent=p.shade;$('#detailHex').textContent=p.hex;$('#detailSwatch').style.setProperty('--detail',p.hex);$('#detailPrice').textContent=`₹${p.price}`;$('#detailMrp').textContent=`₹${p.mrp}`;$('#detailRating').textContent=`${p.rating} ★`;$('#detailReviews').textContent=`${p.reviews.toLocaleString('en-IN')} Ratings, ${Math.round(p.reviews*.18).toLocaleString('en-IN')} Reviews`;$('#detailMatch').textContent=`${matchScore(p.hex)}% shade match`;$('#detailSpecs').innerHTML=`<div><span>Product type</span><b>${p.type}</b></div><div><span>Finish</span><b>${p.finish}</b></div><div><span>Shade family</span><b>${p.family}</b></div><div><span>Net quantity</span><b>1 unit</b></div>`;const rgb=hexToRgb(p.hex),lab=hexToLab(p.hex);$('#passportSwatch').style.setProperty('--passport',p.hex);$('#passportHex').textContent=p.hex;$('#passportRgb').textContent=`${rgb.r}, ${rgb.g}, ${rgb.b}`;$('#passportLab').textContent=`${Math.round(lab.L)}, ${Math.round(lab.a)}, ${Math.round(lab.b)}`;$('#passportFinish').textContent=p.finish;$('#detailShadeOptions').innerHTML=closest(8).map(x=>`<button type="button" class="${x.id===p.id?'is-active':''}" style="--shade:${x.hex}" data-detail-shade="${x.id}" aria-label="View ${x.shade}"></button>`).join('');$$('[data-detail-shade]').forEach(button=>button.addEventListener('click',()=>openProduct(button.dataset.detailShade)));const similar=products.filter(x=>x.id!==p.id).sort((a,b)=>distance(p.hex,a.hex)-distance(p.hex,b.hex)).slice(0,5);$('#similarGrid').innerHTML=similar.map(x=>productCard(x,true)).join('');wireProductCards($('#similarGrid'));window.scrollTo({top:0,behavior:'smooth'})}
function showListing(){stopAllCameras();$('#productView').hidden=true;$('#listingView').hidden=false;window.scrollTo({top:0,behavior:'smooth'})}
function openDialog(id){const dialog=$(`#${id}`);if(dialog&&!dialog.open)dialog.showModal()}
function closeDialog(dialog){if(dialog?.open)dialog.close()}

// Precise camera and image colour picker
const scan={stage:$('#scanStage'),video:$('#scanVideo'),canvas:$('#scanCanvas'),empty:$('#scanEmpty'),marker:$('#scanMarker'),loupe:$('#scanLoupe'),button:$('#scanCamera'),status:$('#scanStatus')};
function stopScan(){if(state.scanStream){state.scanStream.getTracks().forEach(track=>track.stop());state.scanStream=null}scan.video.srcObject=null}
async function startScan(){stopScan();try{state.scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});scan.video.srcObject=state.scanStream;await scan.video.play();scan.stage.className='camera-stage has-video';scan.button.textContent='Capture frame';scan.button.dataset.mode='capture';scan.status.textContent='Live · frame the colour, then capture'}catch(error){toast(error?.name==='NotAllowedError'?'Camera permission was not granted.':'Camera is unavailable. Upload a photo instead.')};}
function captureScan(){if(!scan.video.videoWidth)return;scan.canvas.width=scan.video.videoWidth;scan.canvas.height=scan.video.videoHeight;scan.canvas.getContext('2d',{willReadFrequently:true}).drawImage(scan.video,0,0);stopScan();scan.stage.className='camera-stage has-image';scan.button.textContent='Retake';scan.button.dataset.mode='retake';scan.status.textContent='Frame frozen · tap any visible pixel';scan.marker.hidden=true;scan.loupe.hidden=true}
function loadScanFile(file){if(!file)return;const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{const scale=Math.min(1,1920/Math.max(image.naturalWidth,image.naturalHeight));scan.canvas.width=Math.round(image.naturalWidth*scale);scan.canvas.height=Math.round(image.naturalHeight*scale);scan.canvas.getContext('2d',{willReadFrequently:true}).drawImage(image,0,0,scan.canvas.width,scan.canvas.height);URL.revokeObjectURL(url);scan.stage.className='camera-stage has-image';scan.button.textContent='Start camera';scan.button.dataset.mode='';scan.status.textContent='Photo ready · tap any visible pixel';scan.marker.hidden=true;scan.loupe.hidden=true};image.src=url}
function canvasPoint(event,canvas){const rect=canvas.getBoundingClientRect(),ratio=canvas.width/canvas.height,box=rect.width/rect.height;let width,height,offX=0,offY=0;if(ratio>box){width=rect.width;height=width/ratio;offY=(rect.height-height)/2}else{height=rect.height;width=height*ratio;offX=(rect.width-width)/2}const px=event.clientX-rect.left-offX,py=event.clientY-rect.top-offY;if(px<0||py<0||px>width||py>height)return null;return{x:px/width*canvas.width,y:py/height*canvas.height,screenX:event.clientX-scan.stage.getBoundingClientRect().left,screenY:event.clientY-scan.stage.getBoundingClientRect().top}}
function median(values){const sorted=values.slice().sort((a,b)=>a-b);return sorted[Math.floor(sorted.length/2)]}
function samplePixel(ctx,x,y){x=clamp(Math.round(x),0,ctx.canvas.width-1);y=clamp(Math.round(y),0,ctx.canvas.height-1);const centre=ctx.getImageData(x,y,1,1).data;if(centre[3]<200)return{transparent:true,x,y};const centreLab=rgbToLab(centre[0],centre[1],centre[2]),sx=Math.max(0,x-2),sy=Math.max(0,y-2),ex=Math.min(ctx.canvas.width-1,x+2),ey=Math.min(ctx.canvas.height-1,y+2),data=ctx.getImageData(sx,sy,ex-sx+1,ey-sy+1).data,samples=[];for(let i=0;i<data.length;i+=4){if(data[i+3]<200)continue;const lab=rgbToLab(data[i],data[i+1],data[i+2]);if(Math.hypot(lab.L-centreLab.L,lab.a-centreLab.a,lab.b-centreLab.b)<=14)samples.push([data[i],data[i+1],data[i+2]])}return{x,y,centre:rgbToHex(centre[0],centre[1],centre[2]),hex:rgbToHex(median(samples.map(c=>c[0])),median(samples.map(c=>c[1])),median(samples.map(c=>c[2])))} }
function drawLoupe(result,point){const ctx=scan.loupe.getContext('2d'),size=13,sx=clamp(result.x-6,0,scan.canvas.width-size),sy=clamp(result.y-6,0,scan.canvas.height-size);ctx.clearRect(0,0,96,96);ctx.imageSmoothingEnabled=false;ctx.drawImage(scan.canvas,sx,sy,size,size,0,0,96,96);ctx.strokeStyle='#fff';ctx.beginPath();ctx.moveTo(48,0);ctx.lineTo(48,96);ctx.moveTo(0,48);ctx.lineTo(96,48);ctx.stroke();scan.marker.style.left=`${point.screenX}px`;scan.marker.style.top=`${point.screenY}px`;scan.marker.hidden=false;scan.loupe.style.left=`${clamp(point.screenX+24,8,scan.stage.clientWidth-98)}px`;scan.loupe.style.top=`${clamp(point.screenY>120?point.screenY-108:point.screenY+24,8,scan.stage.clientHeight-98)}px`;scan.loupe.hidden=false}
function updateScan(hex,quality){const rgb=hexToRgb(hex);$('#scanColour').style.setProperty('--scan',hex);$('#scanHex').textContent=hex;$('#scanRgb').textContent=`RGB ${rgb.r}, ${rgb.g}, ${rgb.b}`;$('#scanQuality').textContent=quality;setReference(hex)}
function renderScanMatches(){if(!$('#scanMatches'))return;$('#scanMatches').innerHTML=closest(4).map(p=>`<div class="scan-match"><i style="--c:${p.hex}"></i><span><b>${p.shade}</b><small>${p.brand} · ${p.hex}</small></span><b>${matchScore(p.hex)}%</b></div>`).join('')}

// Face try-on
const tryOn=new window.ShadeTryOn({video:$('#tryOnVideo'),canvas:$('#tryOnCanvas'),stage:$('#tryOnStage'),onStatus:(kind,message)=>{$('#tryOnStatus').textContent=message;$('#tryOnHint').textContent=kind==='live'?'Find your face':message;$('#tryOnStage').classList.toggle('searching',kind!=='live')}});
function setTryColour(region,hex,button){tryOn.set(region,{hex});const holder=button.parentElement;$$('button',holder).forEach(x=>x.classList.toggle('is-active',x===button))}
function buildTryOn(){const values=[state.activeHex,...products.map(p=>p.hex)].filter((v,i,a)=>a.indexOf(v)===i).slice(0,10),brows=['#2C1B18','#4A3029','#68463A','#7A5848','#936E5A'],eyes=['#8A5D70','#9C7566','#75516C','#A97862','#6E587F','#A48B70'];[["#tryLipSwatches",values,'lips'],['#tryBrowSwatches',brows,'brows'],['#tryEyeSwatches',eyes,'eyes']].forEach(([selector,colours,region])=>{const holder=$(selector);holder.innerHTML=colours.map((hex,index)=>`<button type="button" class="${index===0?'is-active':''}" style="--swatch:${hex}" data-colour="${hex}" aria-label="Use ${hex}"></button>`).join('');tryOn.set(region,{hex:colours[0]});$$('button',holder).forEach(button=>button.addEventListener('click',()=>setTryColour(region,button.dataset.colour,button)))})}
function openFace(product){buildTryOn();if(product){tryOn.set('lips',{hex:product.hex});$('#tryLipSwatches').insertAdjacentHTML('afterbegin',`<button type="button" class="is-active" style="--swatch:${product.hex}" data-colour="${product.hex}" aria-label="Use ${product.hex}"></button>`);const first=$('#tryLipSwatches button');first.addEventListener('click',()=>setTryColour('lips',product.hex,first))}openDialog('tryOnDialog')}

// Live hand and skin swatch comparison
function stopSkin(){cancelAnimationFrame(state.skinLoop);if(state.skinStream){state.skinStream.getTracks().forEach(track=>track.stop());state.skinStream=null}$('#skinVideo').srcObject=null}
function seedSkin(product){const base=product||state.selected||closest(1)[0];const nearby=products.filter(p=>p.id!==base.id).sort((a,b)=>distance(base.hex,a.hex)-distance(base.hex,b.hex)).slice(0,2);state.skinShades=[base.id,...nearby.map(p=>p.id)].slice(0,4);renderSkinControls();drawSkin()}
function openSkin(product){if(product)seedSkin(product);else if(state.compare.length)state.skinShades=state.compare.slice(0,4);else if(!state.skinShades.length)seedSkin(closest(1)[0]);renderSkinControls();openDialog('skinDialog');drawSkin()}
function renderSkinControls(){const list=state.skinType==='Brow'?products.filter(p=>p.type==='Brow').concat(products.filter(p=>p.family==='Brown').slice(0,5)):products;$('#skinPalette').innerHTML=list.slice(0,12).map(p=>`<button type="button" class="${state.skinShades.includes(p.id)?'is-active':''}" data-skin-shade="${p.id}"><i style="--c:${p.hex}"></i><span>${p.shade}</span></button>`).join('');$$('[data-skin-shade]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.skinShade,index=state.skinShades.indexOf(id);if(index>=0)state.skinShades.splice(index,1);else if(state.skinShades.length<4)state.skinShades.push(id);else return toast('Remove one shade before adding another.');renderSkinControls();drawSkin()}));const chosen=state.skinShades.map(id=>products.find(p=>p.id===id)).filter(Boolean);$('#skinComparison').innerHTML=chosen.map(p=>`<div><i style="--c:${p.hex}"></i><span><b>${p.shade}</b><small>${p.brand} · ${p.finish}</small></span><code>${p.hex}</code></div>`).join('')||'<p class="privacy-copy">Choose at least one shade.</p>'}
function roundRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}
function drawSkin(){const canvas=$('#skinCanvas'),ctx=canvas.getContext('2d'),chosen=state.skinShades.map(id=>products.find(p=>p.id===id)).filter(Boolean);ctx.clearRect(0,0,canvas.width,canvas.height);if(!chosen.length)return;const total=Math.min(canvas.width*.72,560),gap=Math.max(6,canvas.width*.008),width=(total-gap*(chosen.length-1))/chosen.length,height=Math.min(canvas.height*.19,120),startX=clamp(state.skinAnchor.x*canvas.width-total/2,12,canvas.width-total-12),startY=clamp(state.skinAnchor.y*canvas.height-height/2,12,canvas.height-height-34),alpha=state.skinType==='Tint'?.5:state.skinType==='Eyeshadow'?.44:state.skinType==='Brow'?.66:.82;chosen.forEach((p,index)=>{const x=startX+index*(width+gap);ctx.save();ctx.globalAlpha=alpha;ctx.fillStyle=p.hex;roundRect(ctx,x,startY,width,height,Math.min(18,width*.12));ctx.fill();ctx.globalAlpha=.28;ctx.fillStyle='#fff';roundRect(ctx,x+4,startY+4,Math.max(5,width*.12),height-8,8);ctx.fill();ctx.restore();ctx.fillStyle='rgba(25,8,19,.78)';roundRect(ctx,x,startY+height+5,width,22,5);ctx.fill();ctx.fillStyle='#fff';ctx.font=`${Math.max(10,canvas.width*.012)}px Arial`;ctx.textAlign='center';ctx.fillText(p.shade.slice(0,15),x+width/2,startY+height+20)});if(state.skinStream)state.skinLoop=requestAnimationFrame(drawSkin)}
async function startSkin(){stopSkin();$('#skinPhoto').hidden=true;try{state.skinStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});const video=$('#skinVideo');video.srcObject=state.skinStream;await video.play();$('#skinCanvas').width=video.videoWidth||1280;$('#skinCanvas').height=video.videoHeight||720;$('#skinStage').classList.add('is-active');drawSkin()}catch(error){toast(error?.name==='NotAllowedError'?'Camera permission was not granted.':'Camera is unavailable. Upload a photo instead.')};}
function loadSkinPhoto(file){if(!file)return;stopSkin();const url=URL.createObjectURL(file),image=$('#skinPhoto');image.onload=()=>{$('#skinCanvas').width=image.naturalWidth;$('#skinCanvas').height=image.naturalHeight;image.hidden=false;$('#skinStage').classList.add('is-active');URL.revokeObjectURL(url);drawSkin()};image.src=url}
function stopAllCameras(){stopScan();tryOn.stop();stopSkin()}

// Event wiring
$('#homeButton').addEventListener('click',showListing);$('#backToResults').addEventListener('click',showListing);$('#scanOpen').addEventListener('click',()=>openDialog('scanDialog'));$('#changeReference').addEventListener('click',()=>openDialog('scanDialog'));$('#faceOpen').addEventListener('click',()=>openFace());$('#skinOpen').addEventListener('click',()=>openSkin());$('#detailFaceTry').addEventListener('click',()=>openFace(state.selected));$('#detailSkinTry').addEventListener('click',()=>openSkin(state.selected));$('#openSkinCompare').addEventListener('click',()=>openSkin());$('#clearCompare').addEventListener('click',()=>{state.compare=[];renderCompare();renderProducts()});
$$('[data-close]').forEach(button=>button.addEventListener('click',()=>{const dialog=button.closest('dialog');if(dialog.id==='tryOnDialog')tryOn.stop();if(dialog.id==='skinDialog')stopSkin();if(dialog.id==='scanDialog')stopScan();closeDialog(dialog)}));
$('#searchInput').addEventListener('input',event=>{state.search=event.target.value;renderProducts()});$('#clearSearch').addEventListener('click',()=>{$('#searchInput').value='';state.search='';renderProducts()});$('#sortSelect').addEventListener('change',renderProducts);$$('.filters input').forEach(input=>input.addEventListener('change',renderProducts));$$('#familyFilters button').forEach(button=>button.addEventListener('click',()=>{state.family=button.dataset.family;$$('#familyFilters button').forEach(x=>x.classList.toggle('is-active',x===button));renderProducts()}));$('#resetFilters').addEventListener('click',()=>{$$('.filters input[type=checkbox]').forEach(x=>x.checked=x.name==='type');state.family='All';$$('#familyFilters button').forEach(x=>x.classList.toggle('is-active',x.dataset.family==='All'));renderProducts()});
scan.button.addEventListener('click',()=>scan.button.dataset.mode==='capture'?captureScan():startScan());$('#scanUpload').addEventListener('click',()=>$('#scanInput').click());$('#scanInput').addEventListener('change',event=>loadScanFile(event.target.files[0]));scan.canvas.addEventListener('pointerdown',event=>{if(!scan.stage.classList.contains('has-image'))return;const point=canvasPoint(event,scan.canvas);if(!point)return;const result=samplePixel(scan.canvas.getContext('2d',{willReadFrequently:true}),point.x,point.y);scan.marker.style.left=`${point.screenX}px`;scan.marker.style.top=`${point.screenY}px`;scan.marker.hidden=false;if(result.transparent){scan.loupe.hidden=true;$('#scanQuality').textContent='That point is transparent. Tap a visible product or swatch.';return}drawLoupe(result,point);updateScan(result.hex,`Pixel ${result.x}, ${result.y} · centre ${result.centre} · 5 × 5 median ${result.hex}`)});$('#applyScan').addEventListener('click',()=>{closeDialog($('#scanDialog'));$('#sortSelect').value='match';renderProducts();showListing()});
$('#startTryOn').addEventListener('click',()=>tryOn.start());$('#stopTryOn').addEventListener('click',()=>tryOn.stop());$('#tryLipsOn').addEventListener('change',event=>tryOn.set('lips',{on:event.target.checked}));$('#tryBrowsOn').addEventListener('change',event=>tryOn.set('brows',{on:event.target.checked}));$('#tryEyesOn').addEventListener('change',event=>tryOn.set('eyes',{on:event.target.checked}));[['#tryLipIntensity','lips'],['#tryBrowIntensity','brows'],['#tryEyeIntensity','eyes']].forEach(([selector,region])=>$(selector).addEventListener('input',event=>tryOn.set(region,{intensity:event.target.value/100})));$$('#tryLipFinish button').forEach(button=>button.addEventListener('click',()=>{$$('#tryLipFinish button').forEach(x=>x.classList.toggle('is-active',x===button));tryOn.set('lips',{finish:button.dataset.finish})}));$$('#tryEyeFinish button').forEach(button=>button.addEventListener('click',()=>{$$('#tryEyeFinish button').forEach(x=>x.classList.toggle('is-active',x===button));tryOn.set('eyes',{finish:button.dataset.finish})}));$('#faceToSkin').addEventListener('click',()=>{tryOn.stop();closeDialog($('#tryOnDialog'));openSkin(state.selected)});
$('#skinStart').addEventListener('click',startSkin);$('#skinStop').addEventListener('click',()=>{stopSkin();$('#skinStage').classList.remove('is-active')});$('#skinUpload').addEventListener('click',()=>$('#skinInput').click());$('#skinInput').addEventListener('change',event=>loadSkinPhoto(event.target.files[0]));$('#skinType').addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;state.skinType=button.dataset.type;$$('#skinType button').forEach(x=>x.classList.toggle('is-active',x===button));renderSkinControls();drawSkin()});$('#skinStage').addEventListener('pointerdown',event=>{const rect=$('#skinStage').getBoundingClientRect();state.skinAnchor={x:clamp((event.clientX-rect.left)/rect.width,.12,.88),y:clamp((event.clientY-rect.top)/rect.height,.15,.75)};drawSkin()});
document.addEventListener('click',event=>{if(event.target.closest('.purchase-row button'))toast('Added to the demo shopping flow.');if(event.target.closest('.seller-card button'))toast('Seller profile opened in the demo.');if(event.target.closest('.creator-image button'))toast('Creator proof video is represented by the linked demo card.')});window.addEventListener('pagehide',stopAllCameras);
function registerTools(){if(!document.modelContext?.registerTool)return;const register=config=>{try{document.modelContext.registerTool(config)}catch{}};register({name:'get_current_shade_results',description:'Read the active colour reference and closest visible products.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute(){return{reference:state.activeHex,products:closest(5).map(p=>({brand:p.brand,shade:p.shade,hex:p.hex,price:p.price}))}}});register({name:'set_colour_reference',description:'Set a six-digit HEX colour and rerank shade results.',inputSchema:{type:'object',properties:{hex:{type:'string',pattern:'^#?[0-9A-Fa-f]{6}$'}},required:['hex'],additionalProperties:false},execute({hex}){if(!/^#?[0-9A-Fa-f]{6}$/.test(hex))throw new Error('Enter a six-digit HEX colour.');setReference('#'+hex.replace('#',''));return{reference:state.activeHex,closest:closest(3).map(p=>p.shade)}}})}
setReference(state.activeHex);renderProducts();renderCompare();buildTryOn();seedSkin(products[0]);renderScanMatches();registerTools();
